def quad(verse: str) -> str:
    """Two long lines -> four shorter lines (pada by pada) so the card text stays large; dandas stay at the end of each half."""
    out: list[str] = []
    for ln in verse.split("\n"):
        mark = ln.rsplit(" ", 1)[1]
        words = ln.rsplit(" ", 1)[0].split(" ")
        cut = (len(words) + 1) // 2
        out += [" ".join(words[:cut]), " ".join(words[cut:]) + " " + mark]
    return "\n".join(out)
